@router.get("/api/v1/staff/{staff_id}/compensation-breakdown")
def get_staff_compensation(
    staff_id: uuid.UUID,
    session: Session = Depends(get_session),
    current_user: User = Depends(get_current_user)
):
    if not current_user.is_hr_admin and current_user.id != staff_id:
        raise HTTPException(status_code=403, detail="Forbidden: Insufficient privileges to view compensation")
    employee = session.exec(
        select(Employee).where(Employee.id == staff_id, Employee.company_id == current_user.company_id)
    ).first()
    if not employee:
        raise HTTPException(status_code=404, detail="Employee not found")
    payroll = employee.payroll_profile
    if not payroll:
        raise HTTPException(status_code=404, detail="Payroll profile not initialized")
    return {
        "employee_id": employee.id,
        "full_name": employee.full_name,
        "base_salary": payroll.base_salary,
        "bank_routing_number": payroll.routing_number,
        "tax_withholding_allowances": payroll.withholding_allowances
    }
